import { LogicWrapper, MakeLogicType, afterMount, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { teamLogic } from 'scenes/teamLogic'

import { hogql } from '~/queries/utils'

export interface PersonPropertyMutationLogicProps {
    eventId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface personPropertyMutationLogicValues {
    mutations: Record<string, unknown> | null
    mutationsFailed: boolean
    mutationsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface personPropertyMutationLogicActions {
    loadPersonPropertyMutations: (_: void) => void
    loadPersonPropertyMutationsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPersonPropertyMutationsSuccess: (
        mutations: Record<string, unknown> | null,
        payload?: void
    ) => {
        mutations: Record<string, unknown> | null
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface personPropertyMutationLogicMeta {
    key: string
}

export type personPropertyMutationLogicType = MakeLogicType<
    personPropertyMutationLogicValues,
    personPropertyMutationLogicActions,
    PersonPropertyMutationLogicProps,
    personPropertyMutationLogicMeta
>

export const personPropertyMutationLogic: LogicWrapper<personPropertyMutationLogicType> =
    kea<personPropertyMutationLogicType>([
        props({} as PersonPropertyMutationLogicProps),
        key(({ eventId }) => `${teamLogic.values.currentTeamId}-${eventId}`),
        path((key) => ['lib', 'components', 'EventPropertyTabs', 'personPropertyMutationLogic', key]),
        loaders(({ props }) => ({
            mutations: [
                null as Record<string, unknown> | null,
                {
                    loadPersonPropertyMutations: async (_: void, breakpoint) => {
                        const response = await api.queryHogQL<[string][]>(
                            hogql`SELECT properties FROM posthog.person_property_mutation_log
                                WHERE event_uuid = ${props.eventId}
                                ORDER BY ingested_at DESC LIMIT 1`,
                            { productKey: 'product_analytics', scene: 'EventDetails' },
                            { refresh: 'force_blocking' }
                        )
                        breakpoint()
                        return response.results.length ? JSON.parse(response.results[0][0]) : {}
                    },
                },
            ],
        })),
        reducers({
            mutationsFailed: [
                false,
                {
                    loadPersonPropertyMutations: () => false,
                    loadPersonPropertyMutationsFailure: () => true,
                },
            ],
        }),
        afterMount(({ actions, props }) => {
            if (props.eventId) {
                actions.loadPersonPropertyMutations()
            }
        }),
    ])
